import os
import subprocess
import re
from flask import Flask, request, jsonify

app = Flask(__name__)

# Configuration
ALLOWED_EXTENSIONS = {'.txt', '.log', '.csv'}
MAX_FILE_SIZE = 10 * 1024 * 1024  # 10MB
BASE_DIR = '/var/app/reports'

def sanitize_filename(filename):
    """Remove potentially dangerous characters from filename."""
    # Allow alphanumeric, dots, hyphens, underscores
    cleaned = re.sub(r'[^a-zA-Z0-9._\-]', '', filename)
    return cleaned

def validate_extension(filename):
    """Check file extension is allowed."""
    _, ext = os.path.splitext(filename)
    return ext.lower() in ALLOWED_EXTENSIONS

@app.route('/api/reports/generate', methods=['POST'])
def generate_report():
    """Generate a report by running a system command with user-specified parameters."""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'No JSON body'}), 400

    report_type = data.get('type', 'summary')
    date_range = data.get('date_range', 'last_7d')
    output_name = data.get('output_name', 'report.txt')

    # Validate output filename
    output_name = sanitize_filename(output_name)
    if not validate_extension(output_name):
        return jsonify({'error': 'Invalid file extension'}), 400

    # Validate report type - only allow known types
    valid_types = ['summary', 'detailed', 'audit', 'compliance']
    if report_type not in valid_types:
        return jsonify({'error': 'Invalid report type'}), 400

    # Build the command - date_range is passed to the reporting tool
    output_path = os.path.join(BASE_DIR, output_name)
    cmd = f'/usr/local/bin/report-gen --type {report_type} --range {date_range} --output {output_path}'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            text=True,
            timeout=30
        )
        if result.returncode == 0:
            return jsonify({'status': 'success', 'file': output_path})
        else:
            return jsonify({'status': 'error', 'detail': result.stderr}), 500
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Report generation timed out'}), 504

@app.route('/api/reports/list', methods=['GET'])
def list_reports():
    """List available reports."""
    try:
        files = os.listdir(BASE_DIR)
        reports = [f for f in files if validate_extension(f)]
        return jsonify({'reports': reports})
    except OSError:
        return jsonify({'reports': []})

@app.route('/api/reports/download', methods=['GET'])
def download_report():
    """Download a specific report file."""
    filename = request.args.get('name', '')
    filename = sanitize_filename(filename)
    if not validate_extension(filename):
        return jsonify({'error': 'Invalid file'}), 400

    filepath = os.path.join(BASE_DIR, filename)
    # Prevent path traversal
    real_path = os.path.realpath(filepath)
    if not real_path.startswith(os.path.realpath(BASE_DIR)):
        return jsonify({'error': 'Access denied'}), 403

    if os.path.exists(filepath):
        with open(filepath, 'r') as f:
            content = f.read()
        return jsonify({'content': content})
    return jsonify({'error': 'Not found'}), 404

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    os.makedirs(BASE_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
